import{_ as u,a0 as f,w as l,s as a,I as e,x as n,a1 as o,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu","title":"每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu.md","filePath":"[post].md"}'),s={name:"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu.md"};function x(b,t,d,m,F,U){const r=f("Link");return l(),a("div",null,[t[17]||(t[17]=e("h1",{id:"每日-ubuntu-小技巧——在-ubuntu-中手動安裝任何版本的-firefox",tabindex:"-1"},[n("每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox "),e("a",{class:"header-anchor",href:"#每日-ubuntu-小技巧——在-ubuntu-中手動安裝任何版本的-firefox","aria-label":"Permalink to “每日 Ubuntu 小技巧——在 Ubuntu 中手動安裝任何版本的 Firefox”"},"​")],-1)),t[18]||(t[18]=e("p",null,"Firefox 是 Ubuntu 中主要的網絡瀏覽器。它預裝在系統中，並添加到默認的 Ubuntu 軟件庫中以獲得 Firefox 最新版本的自動更新。",-1)),t[19]||(t[19]=e("p",null,"大多數用户並不用擔心安裝或使用 Firefox 的問題，因為沒有什麼問題了，它已經安裝並可以使用。你獲取的總是 Firefox 在 Ubuntu 軟件庫中的版本，除非更新 Canonical 的軟件到最新版本。",-1)),t[20]||(t[20]=e("p",null,"現在，如果你想嘗試其它的 Firefox 版本，你就必須手動下載並在 Ubuntu 中安裝它，這個簡短教程將指導你如何正確地在 Ubuntu 中做到這一點。",-1)),t[21]||(t[21]=e("p",null,"因為 Firefox 集成在 Ubuntu 中，如果你試圖完全卸載它，很可能會破壞其它東西。因此要安裝其它版本的最好辦法就是為每個版本分別創建文件夾並進行符號連接。",-1)),t[22]||(t[22]=e("h3",{id:"在-ubuntu-中下載並安裝-firefox",tabindex:"-1"},[n("在 Ubuntu 中下載並安裝 Firefox "),e("a",{class:"header-anchor",href:"#在-ubuntu-中下載並安裝-firefox","aria-label":"Permalink to “在 Ubuntu 中下載並安裝 Firefox”"},"​")],-1)),e("p",null,[t[1]||(t[1]=n("如果你想在 Ubuntu 中手動下載最新版本的 Firefox，進入它的",-1)),o(r,{href:"http://www.mozilla.org/en-US/firefox/all/"},{default:i(()=>[...t[0]||(t[0]=[n("下載頁面",-1)])]),_:1}),t[2]||(t[2]=n("。通過它你將可以獲取到最新版本並安裝它。",-1))]),e("p",null,[t[4]||(t[4]=n("如果你想從初始版本安裝其它版本的 Firefox，",-1)),o(r,{href:"https://ftp.mozilla.org/pub/mozilla.org/firefox/releases/"},{default:i(()=>[...t[3]||(t[3]=[n("訪問這個頁面",-1)])]),_:1}),t[5]||(t[5]=n("。在這你將看到從0.8開始的每個版本。",-1))]),t[23]||(t[23]=p(`<p>下載完你想要的版本之後，切換到 home 目錄下的下載文件夾，因為 Ubuntu 的大多數文件被下載到了這裏。</p><pre><code>cd ~/Downloads
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/firefoxmanualinstall.png" alt=""></p><h3 id="配置-firefox" tabindex="-1">配置 Firefox <a class="header-anchor" href="#配置-firefox" aria-label="Permalink to “配置 Firefox”">​</a></h3><p>由於大多數 Firefox 下載文件以.tar和.bz2格式保存，必須從這些壓縮包中提取文件。有很多方法可以在 Ubuntu 中解壓縮文件。</p><p>比如我下面使用的命令。很容易從.tar和.bz2中提取文件。</p><pre><code>tar -xjf firefox*.tar.bz2
</code></pre><p>解壓後，將會有一個新的 Firefox 文件出現在下載文件夾中。這其中包含了所有的 Firefox 的文件和可執行文件。</p><p>由於我們不想刪除當前安裝的 Firefox，我們必須給每個版本的 Firefox 創建一個單獨的文件夾。因此，對於 Firefox 版本30，使用下面的命令在/opt目錄下創建一個包含新 Firefox 內容的文件夾。</p><pre><code>sudo mv firefox/ /opt/firefox30
</code></pre><p>現在，<strong>/opt/firefox30/</strong>目錄包含的所有文件都是版本30的。</p><h3 id="創建新的-firefox-可執行符號鏈接" tabindex="-1">創建新的 Firefox 可執行符號鏈接 <a class="header-anchor" href="#創建新的-firefox-可執行符號鏈接" aria-label="Permalink to “創建新的 Firefox 可執行符號鏈接”">​</a></h3><p>默認情況下，Firefox 的可執行文件在這個路徑下：<strong>/user/bin/firefox</strong>。我們想要做的是臨時創建一個備份，這樣我們就可以使用我們的自定義安裝的可執行文件。</p><p>要做到這一點，運行下面的命令。</p><pre><code>sudo mv /usr/bin/firefox /usr/bin/firefox-old
</code></pre><p>現在，我們已經從其默認位置移動了 Firefox 的可執行文件，我們必須將默認位置鏈接到我們新的自定義安裝文件。要做到這一點，運行下面的命令來創建我們版本30的一個符號鏈接。</p><pre><code>sudo ln -s /opt/firefox30/firefox /usr/bin/firefox
</code></pre><p>這樣就設置完成了，我們自定義安裝的 Firefox 是 Ubuntu 默認的。每一次啓動 Firefox，它將通過之前的新鏈接加載新的可執行文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/firefoxmanualinstall1.png" alt=""></p><p>以上方法同樣適用於 64-bit 版本的 Firefox。</p><hr>`,21)),e("p",null,[t[7]||(t[7]=n("via: ",-1)),o(r,{href:"http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-manually-install-any-version-of-firefox-in-ubuntu/"},{default:i(()=>[...t[6]||(t[6]=[n("http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-manually-install-any-version-of-firefox-in-ubuntu/",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("譯者：",-1)),o(r,{href:"https://github.com/yechunxiao19"},{default:i(()=>[...t[8]||(t[8]=[n("烏龍茶",-1)])]),_:1}),t[11]||(t[11]=n(" 校對：",-1)),o(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[9]||(t[9]=[n("Caroline",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:i(()=>[...t[13]||(t[13]=[n("Linux中國",-1)])]),_:1}),t[16]||(t[16]=n(" 榮譽推出",-1))])])}const y=u(s,[["render",x]]);export{w as __pageData,y as default};
